// Validate webhook payload — accepts either audit JSON directly
// or a reference to an audit file path.
// Hardened: path traversal, absolute paths, and symlink escapes blocked.

const body = $input.first().json;

if (body.auditPath) {
  const path = require('path');
  const fs = require('fs');

  // Block path traversal and absolute paths
  const raw = String(body.auditPath);
  if (raw.includes('..')) throw new Error('Path traversal rejected');
  if (raw.startsWith('/') || raw.startsWith('\\')) throw new Error('Absolute path rejected');
  if (/^[A-Za-z]:[/\\]/.test(raw)) throw new Error('Windows absolute path rejected');

  // Resolve against safe artifact base directory
  const safeBase = process.env.VANTAGE_ARTIFACT_DIR || path.resolve('/app/artifacts/reports');
  const resolved = path.resolve(safeBase, raw);

  // Use realpathSync to resolve symlinks and verify containment
  let realPath;
  try {
    realPath = fs.realpathSync(resolved);
  } catch (e) {
    throw new Error('auditPath cannot be resolved: ' + raw);
  }

  const normalizedBase = path.normalize(safeBase) + path.sep;
  const normalizedReal = path.normalize(realPath) + path.sep;
  if (!normalizedReal.startsWith(normalizedBase)) {
    throw new Error('Path escapes artifact directory');
  }

  if (!fs.existsSync(realPath)) throw new Error('auditPath not found');
  const audit = JSON.parse(fs.readFileSync(realPath, 'utf8'));
  return [{ json: { audit, source: 'file' } }];
}

if (body.audit) {
  const audit = typeof body.audit === 'string' ? JSON.parse(body.audit) : body.audit;
  return [{ json: { audit, source: 'inline' } }];
}

throw new Error('Missing audit or auditPath in webhook body');

// Deterministic payload preparation — strips oversized artifacts,
// credentials, raw provider payloads, and duplicated data.
// Preserves: scores, finding IDs, rule IDs, URLs, limitations,
// confidence, recommendations, verification methods.
const MAX_FINDINGS = 30, MAX_COMPETITORS = 5, MAX_LIMITATIONS = 20, MAX_KEYWORDS = 20;

const audit = $input.first().json.audit;
const ev = audit.evidence || {};
const site = ev.site || {};
const perf = ev.performance || {};
const business = audit.input?.businessName || site.domain || 'Unknown';

const compact = {
  business: { name: business, domain: site.domain || 'Unknown', platform: site.platform || 'Unknown' },
  scores: _preserveScores(audit.scores || {}),
  bands: {
    conversionReadiness: (audit.bands||{}).conversionReadiness || 'Not Assessed',
    trust: (audit.bands||{}).trust || 'Not Assessed',
    evidenceConfidence: (audit.bands||{}).evidenceConfidence || 'Not Assessed'
  },
  readinessStatus: audit.readinessStatus || 'Unknown',
  assessedWeight: audit.assessedWeight ?? null,
  showNumericScore: audit.showNumericScore !== false,
  evidenceConfidenceScore: audit.evidenceConfidenceScore ?? null,
  rootCause: (audit.rootCause||'').slice(0, 500),
  sourceStatus: {
    website: site.sourceStatus || 'UNKNOWN',
    performance: perf.sourceStatus || 'UNKNOWN',
    competitors: (ev.competitors||[]).length > 0 ? 'SUPPLIED' : 'NONE',
    backlinks: (ev.backlinks||{}).sourceStatus || 'NOT_CONNECTED',
    ga4: (ev.ga4||{}).sourceStatus || 'NOT_CONNECTED',
    gsc: (ev.gsc||{}).sourceStatus || 'NOT_CONNECTED'
  },
  competitors: (ev.competitors||[]).slice(0,MAX_COMPETITORS).map(c=>({url:c.url||c.targetUrl||'',domain:c.domain||'',pageCount:c.pageCount||0,status:c.sourceStatus||'UNKNOWN'})),
  performanceCoverage: { requested: perf.coverage?.requested||0, completed: perf.coverage?.completed||0, failed: perf.coverage?.failed||0, pagesTested: perf.coverage?.pagesTested||0 },
  limitations: [...new Set([...(site.limitations||[]),...(perf.limitations||[]),...((ev.backlinks||{}).limitations||[]),...((ev.ga4||{}).limitations||[]),...((ev.gsc||{}).limitations||[])])].slice(0,MAX_LIMITATIONS),
  findings: (audit.findings||[]).slice(0,MAX_FINDINGS).map(f=>({findingId:f.findingId,ruleId:f.ruleId,title:f.title,severity:f.severity,confidence:f.confidence,scoreBearing:f.scoreBearing,businessImpact:f.businessImpact||'',recommendation:f.recommendation||'',verificationMethod:f.verificationMethod||'',affectedUrls:(f.affectedUrls||[]).slice(0,10),evidence:(f.evidence||[]).slice(0,3).map(er=>({field:er.field,observedValue:er.observedValue})),implementationEffort:f.implementationEffort||'M'})),
  siteMetrics: { pageCount: site.pageCount||0, services:(site.services||[]).slice(0,MAX_KEYWORDS), topicKeywords:(site.topicKeywords||[]).slice(0,MAX_KEYWORDS), platform: site.platform||'Unknown', hasHttps:(site.targetUrl||'').startsWith('https://'), schemaCount:(site.schemaTypes||[]).length, ctaCount:(site.ctas||[]).length, formCount:(site.forms||[]).length },
  trustFlags: { testimonials:!!(site.trust||{}).testimonials, credentials:!!(site.trust||{}).credentials, caseStudies:!!(site.trust||{}).caseStudies, faq:!!(site.trust||{}).faq, pricing:!!(site.trust||{}).pricing, policies:!!(site.trust||{}).policies, contact:!!(site.trust||{}).contact },
  technical: { missingTitles:site.missingTitles||0, missingDescriptions:site.missingDescriptions||0, h1Missing:site.h1Missing||0, h1Multiple:site.h1Multiple||0, imagesMissingAlt:site.imagesMissingAlt||0, internalLinkCount:site.internalLinkCount||0 }
};

if (audit.renderingDiagnostics && audit.renderingDiagnostics.length > 0) {
  compact.renderingDiagnostics = audit.renderingDiagnostics.map(d=>({code:d.diagnosticCode,category:d.diagnosticCategory,explanation:d.clientExplanation,confidence:d.confidence}));
}
if (audit._gate) {
  compact.gateRecommendation = audit._gate.commercialRecommendation||'';
  compact.gateNextAction = audit._gate.nextAction||'';
  compact.gateServiceCategories = audit._gate.serviceCategories||[];
}

function _preserveScores(s){const out={};for(const k of ['trust','contentDepth','conversionPathways','technical','performance','conversionReadiness','awareness','consideration','decision','aiReadiness','conversionPathwaysDimension','trustEatDimension','contentFunnelDimension','technicalPerformanceDimension','entitySchemaAiDimension']){if(k in s)out[k]=s[k];}return out;}

return [{ json: compact }];

// Validate compact payload before GPT processing
const p = $input.first().json;
const required = ['scores','findings','sourceStatus'];
for (const key of required) {
  if (!p[key]) throw new Error('Missing required key: ' + key);
}
if (!Array.isArray(p.findings) || p.findings.length === 0) {
  throw new Error('Payload must contain at least one finding');
}
if (p.scores.performance == null || p.scores.conversionReadiness == null) {
  throw new Error('Required scores missing');
}
const json = JSON.stringify(p);
if (/will increase (traffic|leads|revenue|sales|bookings) by \d+%/i.test(json)) {
  throw new Error('Unsupported numeric claims detected');
}
for (const f of p.findings) {
  if (!f.findingId || !f.ruleId) throw new Error('Finding missing ID: ' + JSON.stringify(f.title));
}
if (json.length > 100000) throw new Error('Payload exceeds 100KB');
return [{ json: p }];

// Validate GPT output — reject invented findings, unsupported claims
const item = $input.first().json;
// Parse GPT response: may be message.content string or already parsed
let content;
if (typeof item === 'string') {
  content = JSON.parse(item);
} else if (item.message?.content) {
  content = typeof item.message.content === 'string' ? JSON.parse(item.message.content) : item.message.content;
} else {
  content = item;
}

// Verify required sections exist
if (!content.reportNarrative) {
  throw new Error('GPT output missing reportNarrative');
}

// Reject unsupported claims in the full output
const str = JSON.stringify(content);
if (/will increase (traffic|leads|revenue|sales|bookings) by \d+%/i.test(str)) {
  throw new Error('GPT produced unsupported numeric claims');
}
if (/guaranteed|promised|certain to/i.test(str) && /(traffic|leads|revenue|sales|bookings)/i.test(str)) {
  throw new Error('GPT produced guaranteed outcome claim');
}

// Verify finding IDs against original payload
const origNode = $('Validate Compact Output');
if (!origNode || !origNode.first()) throw new Error('Original payload not found for validation');
const original = origNode.first().json;
const origIds = new Set(original.findings.map(f => f.ruleId));

// Check all referencedFindingIds across the output
const allRefs = [
  ...(content.referencedFindingIds || []),
  ...(content.executiveInterpretation?.referencedFindingIds || []),
  ...(content.executiveInterpretation?.rootCause?.supportingFindingIds || []),
  ...(content.priorityGroups || []).flatMap(g => g.findingIds || [])
];
for (const id of allRefs) {
  if (!origIds.has(id)) {
    throw new Error('GPT referenced non-existent finding ID: ' + id);
  }
}

return [{ json: { gpt: content, payload: original } }];

// Assemble a multi-page static HTML report with shared CSS and navigation.
// Produces file contents in-memory for the ZIP generator.

const data = $input.first().json;
const payload = data.payload;
const gpt = data.gpt || {};
const business = payload.business?.name || 'Client';

const CSS = `:root{--bg:#fafaf9;--card:#fff;--text:#1a1a1a;--muted:#6b6b6b;--border:#e5e5e5;--accent:#2563eb;--accent-light:#dbeafe;--red:#dc2626;--amber:#d97706;--green:#16a34a;--slate:#475569;--radius:8px}*{box-sizing:border-box;margin:0;padding:0}body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;background:var(--bg);color:var(--text);line-height:1.6}.container{max-width:960px;margin:0 auto;padding:24px 20px}header{padding:18px 0 12px}header .container{display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:16px;background:linear-gradient(135deg,#123a72,#2563eb);border-radius:16px;padding:26px 24px;color:#fff}header h1{font-size:1.75rem;font-weight:800}.top-nav{position:sticky;top:0;z-index:100;background:var(--bg);border-bottom:1px solid var(--border);margin-bottom:20px}.top-nav .container{padding:10px 20px}.nav-list{display:flex;gap:8px;list-style:none;overflow-x:auto}.nav-list a{display:block;padding:9px 13px;font-size:.78rem;font-weight:700;color:var(--slate);text-decoration:none;border:1px solid var(--border);border-radius:8px;background:var(--card)}.nav-list a.active,.nav-list a:hover{color:#fff;border-color:var(--accent);background:var(--accent)}section{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);padding:24px;margin-bottom:20px}section h2{font-size:1.2rem;font-weight:700;margin-bottom:16px;padding-bottom:8px;border-bottom:2px solid var(--accent-light)}.score-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px;margin:16px 0}.score-card{text-align:center;padding:16px;border-radius:var(--radius);border:1px solid var(--border)}.score-card .value{font-size:2rem;font-weight:700}.score-green .value{color:var(--green)}.score-amber .value{color:var(--amber)}.score-red .value{color:var(--red)}table{width:100%;border-collapse:collapse;font-size:.9rem;margin:12px 0}th,td{text-align:left;padding:10px 12px;border-bottom:1px solid var(--border)}th{background:#f8fafc;font-weight:600;font-size:.8rem;text-transform:uppercase;color:var(--slate)}.sev-high{color:var(--red);font-weight:600}.sev-med{color:var(--amber)}.sev-low{color:var(--slate)}footer{text-align:center;padding:32px 20px;color:var(--muted);font-size:.8rem;border-top:1px solid var(--border);margin-top:40px}@media(max-width:768px){header .container{flex-direction:column}}@media print{.top-nav{display:none!important}body{font-size:11pt;color:#000}section{box-shadow:none;border:1px solid #ddd;break-inside:avoid}@page{margin:15mm}}`;

const TOML = '[build]\npublish = "."\n\n[[redirects]]\n  from = "/*"\n  to = "/index.html"\n  status = 200\n\n[[headers]]\n  for = "/*"\n  [headers.values]\n    X-Frame-Options = "DENY"\n    X-Content-Type-Options = "nosniff"\n';

const PAGES = [
  { id:'01-executive-summary', title:'Executive Summary', nav:'Summary' },
  { id:'02-priority-fixes', title:'Priority Fixes', nav:'Priorities' },
  { id:'03-performance', title:'Performance & Diagnostics', nav:'Performance' },
  { id:'04-evidence', title:'Evidence & Sources', nav:'Evidence' },
  { id:'05-next-steps', title:'Next Steps', nav:'Next Steps' }
];

function esc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function navHtml(cid){ return PAGES.map(p=>`<li><a href="${esc(p.id)}.html"${p.id===cid?' class="active"':''}>${esc(p.nav)}</a></li>`).join(''); }
function shell(id,title,nav,body,foot){ return `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>${esc(title)} — Pryzm Client Report</title><style>${CSS}</style></head><body><header><div class="container"><div><span style="background:rgba(255,255,255,.18);color:#fff;padding:5px 12px;border-radius:100px;font-size:.72rem;font-weight:700">PRYZM PHASE 1 AUDIT</span><h1>${esc(title)}</h1></div></div></header><nav class="top-nav"><div class="container"><ul class="nav-list">${nav}</ul></div></nav><div class="container">${body}</div>${foot}</body></html>`; }
function foot(){ return `<footer><p>Pryzm Client Report for ${esc(business)}</p><p>Generated by Prysm. No outcomes promised without measurement data.</p></footer>`; }
function sc(label,value){ const cls=value>=80?'score-green':value>=60?'score-amber':'score-red'; return `<div class="score-card ${cls}"><div class="value">${value??'—'}</div><div class="label">${esc(label)}</div></div>`; }

const s=payload.scores||{};
const diags=payload.renderingDiagnostics||[];
const f=foot();
const pages={
  'index': shell('index','Pryzm Client Report — '+business,navHtml('index'),`<section><h2>Pryzm Client Report</h2><p>Evidence-grounded website audit for <strong>${esc(business)}</strong></p><p>Domain: ${esc(payload.business?.domain||'N/A')} &middot; Platform: ${esc(payload.business?.platform||'Unknown')}</p><p>Conversion Readiness: <strong>${s.conversionReadiness??'—'}/100</strong> &middot; Assessed Weight: ${payload.assessedWeight??'—'}%</p></section><section><h2>Report Contents</h2><ul>${PAGES.map(p=>`<li><a href="pages/${esc(p.id)}.html">${esc(p.title)}</a></li>`).join('')}</ul></section>`,f),
  '01-executive-summary': shell('01-executive-summary','Executive Summary',navHtml('01-executive-summary'),`<section><h2>Conversion Readiness</h2><div class="score-grid">${sc('Readiness',s.conversionReadiness)}${sc('Trust',s.trust)}${sc('Content',s.contentDepth)}${sc('Performance',s.performance)}</div><p><strong>Status:</strong> ${esc(payload.readinessStatus)} (${payload.assessedWeight}% assessed weight)</p><p><strong>Confidence:</strong> ${esc(payload.bands.evidenceConfidence)}</p><p style="margin-top:16px">${esc(payload.rootCause||'')}</p></section><section><h2>Source Status</h2><table><thead><tr><th>Source</th><th>Status</th></tr></thead><tbody>${Object.entries(payload.sourceStatus||{}).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${esc(v)}</td></tr>`).join('')}</tbody></table></section>`,f),
  '02-priority-fixes': shell('02-priority-fixes','Priority Fixes',navHtml('02-priority-fixes'),`<section><h2>Findings</h2>${payload.findings&&payload.findings.length?`<table><thead><tr><th>Sev</th><th>Finding</th><th>Recommendation</th></tr></thead><tbody>${payload.findings.map(f=>`<tr><td class="sev-${(f.severity||'med').toLowerCase().slice(0,3)}">${esc(f.severity||'')}</td><td><strong>${esc(f.ruleId||'')}</strong>: ${esc(f.title||'')}</td><td>${esc(f.recommendation||'')}</td></tr>`).join('')}</tbody></table>`:'<p>No findings.</p>'}</section><section><h2>Coverage</h2><table><tbody><tr><td>Requested</td><td>${payload.performanceCoverage?.requested||0}</td></tr><tr><td>Completed</td><td>${payload.performanceCoverage?.completed||0}</td></tr><tr><td>Failed</td><td>${payload.performanceCoverage?.failed||0}</td></tr></tbody></table></section>`,f),
  '03-performance': shell('03-performance','Performance & Diagnostics',navHtml('03-performance'),`<section><h2>Performance</h2><div class="score-grid">${sc('Performance',s.performance)}${sc('Technical',s.technical)}</div></section><section><h2>Rendering Diagnostics</h2>${diags.length>0?`<table><thead><tr><th>Code</th><th>Category</th><th>Explanation</th></tr></thead><tbody>${diags.map(d=>`<tr><td>${esc(d.code)}</td><td>${esc(d.category)}</td><td>${esc(d.explanation)}</td></tr>`).join('')}</tbody></table>`:'<p>No rendering defects detected.</p>'}</section>`,f),
  '04-evidence': shell('04-evidence','Evidence & Sources',navHtml('04-evidence'),`<section><h2>Technical Metrics</h2><table><tbody><tr><td>Pages</td><td>${payload.siteMetrics?.pageCount||0}</td></tr><tr><td>Missing Titles</td><td>${payload.technical?.missingTitles||0}</td></tr><tr><td>Missing Descriptions</td><td>${payload.technical?.missingDescriptions||0}</td></tr><tr><td>H1 Missing</td><td>${payload.technical?.h1Missing||0}</td></tr><tr><td>Images Missing Alt</td><td>${payload.technical?.imagesMissingAlt||0}</td></tr></tbody></table></section><section><h2>Trust Signals</h2><table><tbody>${Object.entries(payload.trustFlags||{}).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${v?'Yes':'No'}</td></tr>`).join('')}</tbody></table></section><section><h2>Limitations</h2><ul>${(payload.limitations||[]).map(l=>`<li>${esc(l)}</li>`).join('')}</ul></section>`,f),
  '05-next-steps': shell('05-next-steps','Next Steps',navHtml('05-next-steps'),`<section><h2>Commercial Recommendation</h2><p style="font-size:1.1rem">${esc(payload.gateRecommendation||gpt.reportNarrative?.recommendedPlan||'')}</p></section><section><h2>Required Next Action</h2><p style="font-weight:600">${esc(payload.gateNextAction||'Book an implementation scoping session to determine whether targeted remediation or a full redesign is the better investment.')}</p></section><section><h2>Service Categories</h2><ul>${(payload.gateServiceCategories||[]).map(c=>`<li>${esc(c)}</li>`).join('')}</ul></section><section><h2>Evidence Statement</h2><p>Generated from a completed Pryzm Phase 1 Audit. All findings reference specific evidence sources and rule IDs. No outcomes are promised without supporting measurement data. Provider limitations are documented in the Evidence section.</p></section>`,f)
};
pages['netlify.toml'] = TOML;
pages['css/report.css'] = CSS;

return [{ json: { pages, business, pageCount: Object.keys(pages).length } }];

// Generate a Netlify-ready ZIP binary in-memory using only Node.js built-ins.
// Implements the ZIP file format for uncompressed (store) entries.
// Returns binary data for the Respond with ZIP node.

const data = $input.first().json;
const pages = data.pages || {};
const encoder = new TextEncoder();
const entries = [];
for (const [name, content] of Object.entries(pages)) {
  entries.push({ name, raw: encoder.encode(content), crc: _crc32(encoder.encode(content)) });
}

let dataOffset = 0;
const localHeaders = [];
for (const e of entries) {
  const nb = encoder.encode(e.name);
  const h = Buffer.alloc(30 + nb.length);
  let p = 0;
  h.writeUInt32LE(0x04034b50, p); p += 4;
  h.writeUInt16LE(20, p); p += 2;
  h.writeUInt16LE(0x0800, p); p += 2;
  h.writeUInt16LE(0, p); p += 2;
  h.writeUInt16LE(0, p); p += 2;
  h.writeUInt16LE(0, p); p += 2;
  h.writeUInt32LE(e.crc, p); p += 4;
  h.writeUInt32LE(e.raw.length, p); p += 4;
  h.writeUInt32LE(e.raw.length, p); p += 4;
  h.writeUInt16LE(nb.length, p); p += 2;
  h.writeUInt16LE(0, p);
  h.set(nb, 30);
  localHeaders.push(h);
  e._off = dataOffset;
  dataOffset += h.length + e.raw.length;
}

const centralOffset = dataOffset;
let centralSize = 0;
const centralParts = [];
for (const e of entries) {
  const nb = encoder.encode(e.name);
  const cd = Buffer.alloc(46 + nb.length);
  let p = 0;
  cd.writeUInt32LE(0x02014b50, p); p += 4;
  cd.writeUInt16LE(20, p); p += 2;
  cd.writeUInt16LE(20, p); p += 2;
  cd.writeUInt16LE(0x0800, p); p += 2;
  cd.writeUInt16LE(0, p); p += 2;
  cd.writeUInt16LE(0, p); p += 2;
  cd.writeUInt16LE(0, p); p += 2;
  cd.writeUInt32LE(e.crc, p); p += 4;
  cd.writeUInt32LE(e.raw.length, p); p += 4;
  cd.writeUInt32LE(e.raw.length, p); p += 4;
  cd.writeUInt16LE(nb.length, p); p += 2;
  cd.writeUInt16LE(0, p); p += 2;
  cd.writeUInt16LE(0, p); p += 2;
  cd.writeUInt16LE(0, p); p += 2;
  cd.writeUInt16LE(0, p); p += 2;
  cd.writeUInt32LE(0, p); p += 4;
  cd.writeUInt32LE(e._off, p); p += 4;
  cd.set(nb, 46);
  centralParts.push(cd);
  centralSize += cd.length;
}

const eocd = Buffer.alloc(22);
let ep = 0;
eocd.writeUInt32LE(0x06054b50, ep); ep += 4;
eocd.writeUInt16LE(0, ep); ep += 2;
eocd.writeUInt16LE(0, ep); ep += 2;
eocd.writeUInt16LE(entries.length, ep); ep += 2;
eocd.writeUInt16LE(entries.length, ep); ep += 2;
eocd.writeUInt32LE(centralSize, ep); ep += 4;
eocd.writeUInt32LE(centralOffset, ep); ep += 4;
eocd.writeUInt16LE(0, ep);

const totalSize = dataOffset + centralSize + 22;
const zip = Buffer.alloc(totalSize);
let z = 0;
for (let i = 0; i < entries.length; i++) {
  localHeaders[i].copy(zip, z); z += localHeaders[i].length;
  const rb = entries[i].raw;
  Buffer.from(rb).copy(zip, z); z += rb.length;
}
for (const cd of centralParts) { cd.copy(zip, z); z += cd.length; }
eocd.copy(zip, z);

function _crc32(buf) {
  let crc = 0xFFFFFFFF;
  const data = Buffer.isBuffer(buf) ? buf : Buffer.from(buf);
  for (let i = 0; i < data.length; i++) {
    crc ^= data[i];
    for (let j = 0; j < 8; j++) crc = (crc >>> 1) ^ (crc & 1 ? 0xEDB88320 : 0);
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

const base64 = zip.toString('base64');
return [{
  json: { filename: 'pryzm-report.zip', size: zip.length, pageCount: entries.length },
  binary: { data: { data: base64, mimeType: 'application/zip', fileName: 'pryzm-report.zip', fileSize: zip.length.toString() } }
}];
